input.command:
W=$PWD; uv run ruff check . && uv run ruff format --check . && uv run ty check
rm -rf /tmp/t && mkdir /tmp/t && cd /tmp/t && PYTHONPATH=$W/src python3 -I - <<'E'
import sys; sys.path.insert(0,sys.argv[0] if False else __import__('os').environ['PYTHONPATH'])
from auditlog import search as s
c=s.connect(); c.executemany("insert into audit(actor,action,target,ts) values(?,?,?,?)",[("a","x","t","2026-01-01"),("a","y","t","2026-02-01"),("o'b","x","t","2026-03-01")]);c.commit();c.close()
print(s.search("a",since="2026-01-15"),s.search("a",sort="action",direction="asc",limit=1,offset=1))
try: s.search("a",sort="ts;drop")
except ValueError as e: print(e)
E
PYTHONPATH=$W/src python3 -m auditlog.search --actor a --since 2026-01-15 --limit 1; cd $W; git status --short

